-- Natural Patraix con los sectores numerados (02/11/2026): del 1 al 9 en la sala 1, del 10 al 20 en la sala 2,
-- del 21 al 37 en la sala 3 y 38-39 en la terraza. En el plano cada sector se ve solo con su número.
-- Mientras no se marquen los límites de verdad, cada pared está repartida en tramos iguales.
-- Ejecútalo una vez en Supabase → SQL Editor, después de 011. Los bloques no se tocan.

-- 1) Quitar los sectores antiguos de Patraix (Banda, Zigzag, La U, Isla…)
delete from public.sectors where gym_id = 'patraix' and name not in ('Sala 1 · 1', 'Sala 1 · 2', 'Sala 1 · 3', 'Sala 1 · 4', 'Sala 1 · 5', 'Sala 1 · 6', 'Sala 1 · 7', 'Sala 1 · 8', 'Sala 1 · 9', 'Sala 2 · 10', 'Sala 2 · 11', 'Sala 2 · 12', 'Sala 2 · 13', 'Sala 2 · 14', 'Sala 2 · 15', 'Sala 2 · 16', 'Sala 2 · 17', 'Sala 2 · 18', 'Sala 2 · 19', 'Sala 2 · 20', 'Sala 3 · 21', 'Sala 3 · 22', 'Sala 3 · 23', 'Sala 3 · 24', 'Sala 3 · 25', 'Sala 3 · 26', 'Sala 3 · 27', 'Sala 3 · 28', 'Sala 3 · 29', 'Sala 3 · 30', 'Sala 3 · 31', 'Sala 3 · 32', 'Sala 3 · 33', 'Sala 3 · 34', 'Sala 3 · 35', 'Sala 3 · 36', 'Sala 3 · 37', 'Terraza · 38', 'Terraza · 39');

-- 2) Crear los 39 numerados con su zona en el plano
on conflict (gym_id, name) do update set x = excluded.x, y = excluded.y, shape = excluded.shape;

-- 3) Bloques abiertos que siguen con un sector antiguo (para pasarlos a su número desde la app: Editar → tocar la zona)
select b.sector, count(*) as bloques_abiertos
from public.blocks b
where b.gym_id = 'patraix' and b.active and b.sector is not null
  and b.sector not in ('Sala 1 · 1', 'Sala 1 · 2', 'Sala 1 · 3', 'Sala 1 · 4', 'Sala 1 · 5', 'Sala 1 · 6', 'Sala 1 · 7', 'Sala 1 · 8', 'Sala 1 · 9', 'Sala 2 · 10', 'Sala 2 · 11', 'Sala 2 · 12', 'Sala 2 · 13', 'Sala 2 · 14', 'Sala 2 · 15', 'Sala 2 · 16', 'Sala 2 · 17', 'Sala 2 · 18', 'Sala 2 · 19', 'Sala 2 · 20', 'Sala 3 · 21', 'Sala 3 · 22', 'Sala 3 · 23', 'Sala 3 · 24', 'Sala 3 · 25', 'Sala 3 · 26', 'Sala 3 · 27', 'Sala 3 · 28', 'Sala 3 · 29', 'Sala 3 · 30', 'Sala 3 · 31', 'Sala 3 · 32', 'Sala 3 · 33', 'Sala 3 · 34', 'Sala 3 · 35', 'Sala 3 · 36', 'Sala 3 · 37', 'Terraza · 38', 'Terraza · 39')
group by b.sector order by b.sector;
